CREATE TABLE users (id BIGINT PRIMARY KEY AUTO_INCREMENT, username VARCHAR(32) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, email VARCHAR(120), nickname VARCHAR(50), avatar_url VARCHAR(500), member_expire_at TIMESTAMP NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE templates (id BIGINT PRIMARY KEY, name VARCHAR(50) NOT NULL, category VARCHAR(30) NOT NULL, is_vip BOOLEAN NOT NULL DEFAULT FALSE, color VARCHAR(20), style VARCHAR(30), sort INT NOT NULL, used_count INT NOT NULL DEFAULT 0);
CREATE TABLE resumes (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, template_id BIGINT NOT NULL, title VARCHAR(100) NOT NULL, content JSON NOT NULL, version INT NOT NULL DEFAULT 0, status VARCHAR(20) NOT NULL DEFAULT 'DRAFT', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id), FOREIGN KEY (template_id) REFERENCES templates(id));
CREATE INDEX idx_resumes_user ON resumes(user_id, updated_at);
CREATE TABLE plans (id BIGINT PRIMARY KEY, name VARCHAR(50) NOT NULL, price INT NOT NULL, duration_days INT NOT NULL, features JSON NOT NULL, sort INT NOT NULL);
CREATE TABLE orders (id BIGINT PRIMARY KEY AUTO_INCREMENT, order_no VARCHAR(64) NOT NULL UNIQUE, user_id BIGINT NOT NULL, plan_id BIGINT NOT NULL, amount INT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'CREATED', channel VARCHAR(20) NOT NULL DEFAULT 'MOCK', request_key VARCHAR(64) NOT NULL, transaction_id VARCHAR(100) UNIQUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, paid_at TIMESTAMP NULL, expired_at TIMESTAMP NOT NULL, FOREIGN KEY (user_id) REFERENCES users(id), FOREIGN KEY (plan_id) REFERENCES plans(id), UNIQUE(user_id, request_key));
CREATE INDEX idx_orders_expiry ON orders(status, expired_at);
CREATE TABLE payment_logs (id BIGINT PRIMARY KEY AUTO_INCREMENT, order_id BIGINT NOT NULL, channel VARCHAR(20) NOT NULL, raw_body TEXT NOT NULL, result VARCHAR(30) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (order_id) REFERENCES orders(id));
CREATE TABLE export_logs (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, resume_id BIGINT NOT NULL, template_id BIGINT NOT NULL, status VARCHAR(20) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id));
CREATE INDEX idx_export_quota ON export_logs(user_id, created_at, status);
